  "inlineSchema": "generator client {\n  provider = \"prisma-client-js\"\n}\n\ndatasource db {\n  provider = \"mongodb\"\n  url      = env(\"DATABASE_URL\")\n}\n\nmodel Car {\n  id                 String             @id @default(auto()) @map(\"_id\") @db.ObjectId\n  make               String\n  model              String\n  year               Int\n  price              Float\n  image              String\n  features           String[]\n  createdAt          DateTime           @default(now())\n  updatedAt          DateTime           @updatedAt\n  userId             String?            @db.ObjectId\n  bodyType           String?\n  exShowroomPriceINR Int?\n  region             String             @default(\"US\")\n  specs              Json?\n  category           String?\n  lastServiceDate    DateTime?\n  odometerKm         Int?\n  saleStatus         String             @default(\"for_sale\")\n  user               User?              @relation(fields: [userId], references: [id])\n  favorites          Favorite[]\n  purchaseRequests   PurchaseRequest[]\n  testDrives         TestDriveBooking[]\n}\n\nmodel User {\n  id               String             @id @default(auto()) @map(\"_id\") @db.ObjectId\n  email            String             @unique\n  password         String\n  name             String\n  phone            String? // contact phone\n  createdAt        DateTime           @default(now())\n  lastSeenAt       DateTime? // updated when user hits authenticated endpoints\n  resetToken       String?\n  resetTokenExp    DateTime?\n  role             String             @default(\"user\")\n  locked           Boolean            @default(false)\n  cars             Car[]\n  favorites        Favorite[]\n  serviceBookings  ServiceBooking[]\n  savedSearches    SavedSearch[]\n  testDrives       TestDriveBooking[]\n  purchaseRequests PurchaseRequest[]\n}\n\nmodel AuditLog {\n  id         String   @id @default(auto()) @map(\"_id\") @db.ObjectId\n  actorId    String?  @db.ObjectId\n  action     String\n  targetType String\n  targetId   String?  @db.ObjectId\n  metadata   Json?\n  createdAt  DateTime @default(now())\n\n  @@index([action, createdAt])\n}\n\nmodel FinanceApplication {\n  id        String   @id @default(auto()) @map(\"_id\") @db.ObjectId\n  userId    String   @db.ObjectId\n  amount    Float\n  status    String\n  createdAt DateTime @default(now())\n}\n\nmodel ServiceBooking {\n  id              String                  @id @default(auto()) @map(\"_id\") @db.ObjectId\n  userId          String                  @db.ObjectId\n  user            User                    @relation(fields: [userId], references: [id])\n  carId           String?                 @db.ObjectId\n  service         String\n  date            DateTime\n  status          String\n  amountPaid      Float?\n  contactPhone    String?\n  createdAt       DateTime                @default(now())\n  durationMinutes Int?\n  estimatedCost   Float?\n  internalNotes   String?\n  locationId      String?                 @db.ObjectId\n  notes           String?\n  paymentIntentId String?\n  paymentStatus   String?\n  preferredTime   String?\n  serviceType     String?\n  slotEnd         DateTime?\n  slotStart       DateTime?\n  technicianName  String?\n  updatedAt       DateTime                @updatedAt\n  address         String?\n  bookingCode     String?                 @unique\n  finalCost       Float?\n  invoiceNumber   String?\n  dropOffAt       DateTime?               @db.Timestamp\n  pickUpAt        DateTime?               @db.Timestamp\n  completedAt     DateTime?               @db.Timestamp\n  billNotes       String?\n  cancelReason    String?\n  customCar       String?\n  location        Location?               @relation(fields: [locationId], references: [id])\n  history         ServiceBookingHistory[]\n}\n\nmodel ServiceBookingHistory {\n  id         String         @id @default(auto()) @map(\"_id\") @db.ObjectId\n  bookingId  String         @db.ObjectId\n  fromStatus String?\n  toStatus   String\n  actorId    String?        @db.ObjectId\n  note       String?\n  changedAt  DateTime?      @default(now()) @db.Timestamp\n  booking    ServiceBooking @relation(fields: [bookingId], references: [id], onDelete: Cascade, onUpdate: NoAction)\n\n  @@index([bookingId, changedAt])\n}\n\nmodel Location {\n  id              String             @id @default(auto()) @map(\"_id\") @db.ObjectId\n  name            String\n  address         String?\n  capacityPerSlot Int                @default(3)\n  createdAt       DateTime           @default(now())\n  bookings        ServiceBooking[]\n  testDrives      TestDriveBooking[]\n}\n\nmodel Notification {\n  id           String    @id @default(auto()) @map(\"_id\") @db.ObjectId\n  userId       String    @db.ObjectId\n  bookingId    String?   @db.ObjectId\n  type         String\n  status       String    @default(\"pending\")\n  payload      Json?\n  createdAt    DateTime  @default(now())\n  sentAt       DateTime?\n  attemptCount Int       @default(0)\n  error        String?\n\n  @@index([status, createdAt])\n}\n\nmodel Favorite {\n  id        String   @id @default(auto()) @map(\"_id\") @db.ObjectId\n  userId    String   @db.ObjectId\n  carId     String   @db.ObjectId\n  createdAt DateTime @default(now())\n  car       Car      @relation(fields: [carId], references: [id])\n  user      User     @relation(fields: [userId], references: [id])\n\n  @@unique([userId, carId])\n}\n\n// User intent to purchase a car (lead). Captures snapshot of car + user contact info at time of request.\nmodel PurchaseRequest {\n  id          String   @id @default(auto()) @map(\"_id\") @db.ObjectId\n  carId       String   @db.ObjectId\n  userId      String?  @db.ObjectId\n  name        String\n  email       String\n  phone       String\n  location    String?\n  message     String?\n  status      String   @default(\"pending\") // pending -> contacted -> closed\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n  carSnapshot Json?\n\n  car  Car   @relation(fields: [carId], references: [id])\n  user User? @relation(fields: [userId], references: [id])\n\n  @@index([status, createdAt])\n}\n\n// Saved search criteria for users; criteria stores filters used in /api/cars\nmodel SavedSearch {\n  id             String    @id @default(auto()) @map(\"_id\") @db.ObjectId\n  userId         String    @db.ObjectId\n  name           String\n  criteria       Json\n  createdAt      DateTime  @default(now())\n  lastNotifiedAt DateTime?\n\n  user User @relation(fields: [userId], references: [id])\n\n  @@index([userId, createdAt])\n}\n\n// General contact leads (home page Contact Us)\nmodel ContactLead {\n  id        String   @id @default(auto()) @map(\"_id\") @db.ObjectId\n  name      String\n  email     String\n  phone     String?\n  message   String?\n  createdAt DateTime @default(now())\n  status    String   @default(\"new\") // new -> contacted -> closed\n\n  @@index([status, createdAt])\n}\n\n// Test drive booking requests\nmodel TestDriveBooking {\n  id            String   @id @default(auto()) @map(\"_id\") @db.ObjectId\n  userId        String?  @db.ObjectId\n  carId         String   @db.ObjectId\n  locationId    String?  @db.ObjectId\n  preferredDay  DateTime\n  preferredTime String?\n  status        String   @default(\"requested\") // requested -> confirmed -> completed -> cancelled\n  createdAt     DateTime @default(now())\n  notes         String?\n\n  user     User?     @relation(fields: [userId], references: [id])\n  car      Car       @relation(fields: [carId], references: [id])\n  location Location? @relation(fields: [locationId], references: [id])\n\n  @@index([carId, createdAt])\n}\n",
